INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'accustomed', 'adj.', '/əˈkʌstəmd/', '习惯的;适应的', 'Astronauts soon become accustomed to floating in zero gravity.', '宇航员很快就习惯了在零重力下漂浮。', 'The Call of the Challenger', 1, 0, 'senior', 'wordlist', 'elective4', 'U6', 'become accustomed to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'notion', 'n.', '/ˈnəʊʃ(ə)n/', '概念;观点;看法', 'People have grown used to the notion of space travel.', '人们已经习惯了太空旅行这个概念。', 'The Call of the Challenger', 2, 0, 'senior', 'wordlist', 'elective4', 'U6', 'the notion of space travel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'hazardous', 'adj.', '/ˈhæzədəs/', '危险的;不安全的', 'Everyone knew the first Moon landing was a hazardous undertaking.', '人人都知道首次登月是一项危险的行动。', 'The Call of the Challenger', 3, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a hazardous journey', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'unexceptional', 'adj.', '/ˌʌnɪkˈsepʃ(ə)nəl/', '平常的;普通的', 'By the 1980s, space travel had become unexceptional to the public.', '到了20世纪80年代,太空旅行对公众来说已是平常事。', 'The Call of the Challenger', 4, 0, 'senior', 'wordlist', 'elective4', 'U6', 'seem unexceptional', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shuttle', 'n.', '/ˈʃʌtl/', '航天飞机;穿梭班车', 'The Challenger space shuttle took off on 28 January 1986.', '挑战者号航天飞机于1986年1月28日升空。', 'The Call of the Challenger', 5, 0, 'senior', 'wordlist', 'elective4', 'U6', 'the space shuttle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'excursion', 'n.', '/ɪkˈskɜːʃ(ə)n/', '短途出行;远足', 'This flight was no ordinary excursion into space.', '这次飞行可不是一次普通的太空出行。', 'The Call of the Challenger', 6, 0, 'senior', 'wordlist', 'elective4', 'U6', 'no ordinary excursion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'rekindle', 'v.', '/riːˈkɪndl/', '重新激起;重新唤起', 'Christa hoped to rekindle public interest in the space programme.', '克丽斯塔希望重新唤起公众对太空计划的兴趣。', 'The Call of the Challenger', 7, 0, 'senior', 'wordlist', 'elective4', 'U6', 'rekindle interest', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tragically', 'adv.', '/ˈtrædʒɪkli/', '悲惨地;不幸地', 'Tragically, the teacher never returned to her classroom.', '不幸的是,这位老师再也没能回到她的教室。', 'The Call of the Challenger', 8, 0, 'senior', 'wordlist', 'elective4', 'U6', 'end tragically', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'instantaneously', 'adv.', '/ˌɪnstənˈteɪniəsli/', '瞬间地;即刻地', 'Instantaneously, excitement turned into terror.', '瞬间,兴奋变成了恐惧。', 'The Call of the Challenger', 9, 0, 'senior', 'wordlist', 'elective4', 'U6', 'change instantaneously', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shadow', 'n.', '/ˈʃædəʊ/', '阴影;坏影响;影子', 'The disaster cast a long shadow on people''s hearts.', '这场灾难在人们心头投下了长长的阴影。', 'The Call of the Challenger', 10, 0, 'senior', 'wordlist', 'elective4', 'U6', 'cast a shadow on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'scream', 'v.', '/skriːm/', '尖声大叫;尖叫', 'When the shuttle exploded, the students all started to scream.', '当航天飞机爆炸时,学生们都尖叫起来。', 'The Call of the Challenger', 11, 0, 'senior', 'wordlist', 'elective4', 'U6', 'start screaming', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'suspend', 'v.', '/səˈspend/', '暂停;中止', 'Space shuttle flights were suspended for nearly three years.', '航天飞机的飞行被暂停了将近三年。', 'The Call of the Challenger', 12, 0, 'senior', 'wordlist', 'elective4', 'U6', 'suspend the flights', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'crew', 'n.', '/kruː/', '全体机组人员;全体船员', 'All seven members of the crew were lost in the accident.', '机组的七名成员全部在这场事故中遇难。', 'The Call of the Challenger', 13, 0, 'senior', 'wordlist', 'elective4', 'U6', 'the crew on board', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'simulated', 'adj.', '/ˈsɪmjʊleɪtɪd/', '模拟的;仿真的', 'At the camp I tried a week of simulated space flight.', '在营地我体验了一周的模拟太空飞行。', 'The Call of the Challenger', 14, 0, 'senior', 'wordlist', 'elective4', 'U6', 'simulated space flight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'simulator', 'n.', '/ˈsɪmjʊleɪtə/', '模拟装置;模拟器', 'Trainees practise in a modern flight simulator before any real mission.', '学员在真正执行任务前先在现代飞行模拟器里训练。', 'The Call of the Challenger', 15, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a flight simulator', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lifelike', 'adj.', '/ˈlaɪflaɪk/', '逼真的;生动的', 'The training felt so lifelike that I almost forgot it was not real.', '这训练太逼真了,我几乎忘了它并不是真的。', 'The Call of the Challenger', 16, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a lifelike spacewalk', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'submit', 'v.', '/səbˈmɪt/', '提交;呈递', 'You must submit a short video to apply for the space programme.', '你必须提交一段短视频来申请这个太空项目。', 'The Call of the Challenger', 17, 0, 'senior', 'wordlist', 'elective4', 'U6', 'submit a video', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'awesome', 'adj.', '/ˈɔːs(ə)m/', '了不起的;令人惊叹的', 'Walking in zero gravity was an awesome experience.', '在零重力下行走是一次了不起的体验。', 'The Call of the Challenger', 18, 0, 'senior', 'wordlist', 'elective4', 'U6', 'an awesome experience', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'telescope', 'n.', '/ˈtelɪskəʊp/', '望远镜', 'A powerful telescope lets us see galaxies far beyond our own.', '一台强大的望远镜让我们看到远在自身之外的星系。', 'The Call of the Challenger', 19, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a space telescope', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'angle', 'v.', '/ˈæŋɡ(ə)l/', '斜置;使成角度', 'When the first telescope was angled at the night sky, our view of space changed.', '当第一台望远镜斜对着夜空时,我们对太空的认识改变了。', 'The Call of the Challenger', 20, 0, 'senior', 'wordlist', 'elective4', 'U6', 'angle a telescope', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'galaxy', 'n.', '/ˈɡæləksi/', '星系', 'Our Sun is only one star among billions in the galaxy.', '太阳只是这个星系中数十亿颗恒星之一。', 'The Call of the Challenger', 21, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a distant galaxy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cosmic', 'adj.', '/ˈkɒzmɪk/', '宇宙的', 'The galaxies float like islands of light in a vast cosmic ocean.', '众多星系如同光的岛屿漂浮在浩瀚的宇宙海洋中。', 'The Call of the Challenger', 22, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a cosmic ocean', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'conceivably', 'adv.', '/kənˈsiːvəb(ə)li/', '可以想象地;有可能地', 'On some new planets we might conceivably find life one day.', '在某些新行星上,我们有朝一日有可能找到生命。', 'The Call of the Challenger', 23, 0, 'senior', 'wordlist', 'elective4', 'U6', 'conceivably find life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'subatomic', 'adj.', '/ˌsʌbəˈtɒmɪk/', '亚原子的', 'Dark matter is thought to be made of tiny subatomic particles.', '暗物质被认为是由微小的亚原子粒子构成的。', 'The Call of the Challenger', 24, 0, 'senior', 'wordlist', 'elective4', 'U6', 'subatomic particles', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'particle', 'n.', '/ˈpɑːtɪk(ə)l/', '粒子;微粒', 'These particles are far too small for ordinary telescopes to see.', '这些粒子太小了,普通望远镜根本看不见。', 'The Call of the Challenger', 25, 0, 'senior', 'wordlist', 'elective4', 'U6', 'invisible particles', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'invisible', 'adj.', '/ɪnˈvɪzɪb(ə)l/', '看不见的;无形的', 'Dark matter is invisible to ordinary telescopes.', '暗物质对普通望远镜来说是看不见的。', 'The Call of the Challenger', 26, 0, 'senior', 'wordlist', 'elective4', 'U6', 'invisible to the eye', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'straightforward', 'adj.', '/ˌstreɪtˈfɔːwəd/', '简单的;直接了当的', 'In space, even the most straightforward task can be difficult.', '在太空中,即便最简单的任务也可能很困难。', 'The Call of the Challenger', 27, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a straightforward task', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'self-discipline', 'n.', '/ˌselfˈdɪsɪplɪn/', '自我约束;自律', 'Astronauts need self-discipline to keep their spacecraft clean.', '宇航员需要自律来保持航天器清洁。', 'The Call of the Challenger', 28, 0, 'senior', 'wordlist', 'elective4', 'U6', 'find the self-discipline', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fetch', 'v.', '/fetʃ/', '(去)拿来;取来', 'A vacuum cleaner is handy for fetching items that float out of reach.', '吸尘器很方便,可以拿回那些漂到够不着的地方的物品。', 'The Call of the Challenger', 29, 0, 'senior', 'wordlist', 'elective4', 'U6', 'fetch floating items', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'muscle', 'n.', '/ˈmʌs(ə)l/', '肌肉', 'Without gravity, astronauts'' bones and muscles can become weak.', '没有重力,宇航员的骨骼和肌肉会变得虚弱。', 'The Call of the Challenger', 30, 0, 'senior', 'wordlist', 'elective4', 'U6', 'weak muscles', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pepper', 'n.', '/ˈpepə/', '胡椒粉', 'In space, salt and pepper are provided in liquid form.', '在太空中,盐和胡椒粉以液体形式提供。', 'The Call of the Challenger', 31, 0, 'senior', 'wordlist', 'elective4', 'U6', 'salt and pepper', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sneeze', 'v.', '/sniːz/', '打喷嚏', 'Imagine what would happen if an astronaut caught a cold and began to sneeze.', '想象一下,如果宇航员感冒并开始打喷嚏会怎么样。', 'The Call of the Challenger', 32, 0, 'senior', 'wordlist', 'elective4', 'U6', 'start to sneeze', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'disc', 'n.', '/dɪsk/', '光盘;唱片;圆盘', 'Voyager 1 carries a disc with sounds and images of Earth.', '旅行者1号携带着一张录有地球声音和图像的光盘。', 'The Call of the Challenger', 33, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a golden disc', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'astronaut', 'n.', '/ˈæstrənɔːt/', '宇航员;航天员', 'Every astronaut on board the Apollo 11 mission made it safely back to Earth.', '阿波罗11号上的每一名宇航员都安全返回了地球。', 'The Call of the Challenger', 34, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a brave astronaut', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'satellite', 'n.', '/ˈsætəlaɪt/', '卫星;人造卫星', 'The first satellite was sent into space in 1957.', '第一颗人造卫星于1957年被送入太空。', 'The Call of the Challenger', 35, 0, 'senior', 'wordlist', 'elective4', 'U6', 'launch a satellite', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'launch', 'v.', '/lɔːntʃ/', '发射;启动', 'Crowds waited eagerly to watch the rocket launch.', '人群急切地等着观看火箭发射。', 'The Call of the Challenger', 36, 0, 'senior', 'wordlist', 'elective4', 'U6', 'launch a spacecraft', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'orbit', 'n.', '/ˈɔːbɪt/', '(天体运行的)轨道', 'She planned to teach two lessons from orbit around the Earth.', '她计划在地球轨道上讲两堂课。', 'The Call of the Challenger', 37, 0, 'senior', 'wordlist', 'elective4', 'U6', 'in orbit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gravity', 'n.', '/ˈɡrævəti/', '重力;引力', 'The teacher wanted to explain how gravity worked in space.', '这位老师想解释重力在太空中是如何起作用的。', 'The Call of the Challenger', 38, 0, 'senior', 'wordlist', 'elective4', 'U6', 'zero gravity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mission', 'n.', '/ˈmɪʃ(ə)n/', '任务;使命', 'The whole crew prepared carefully for the dangerous mission.', '全体机组人员为这次危险的任务做了精心准备。', 'The Call of the Challenger', 39, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a space mission', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'spacecraft', 'n.', '/ˈspeɪskrɑːft/', '航天器;宇宙飞船', 'She would first demonstrate the controls of the spacecraft.', '她会首先演示这艘航天器的操控装置。', 'The Call of the Challenger', 40, 0, 'senior', 'wordlist', 'elective4', 'U6', 'control the spacecraft', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'civilian', 'n.', '/səˈvɪliən/', '平民;普通公民', 'An ordinary teacher was about to become the first civilian in space.', '一位普通教师即将成为首位进入太空的平民。', 'The Call of the Challenger', 41, 0, 'senior', 'wordlist', 'elective4', 'U6', 'the first civilian', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'disaster', 'n.', '/dɪˈzɑːstə/', '灾难;灾祸', 'It was the most disastrous space disaster the world had ever seen.', '那是全世界所见过的最严重的太空灾难。', 'The Call of the Challenger', 42, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a space disaster', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'explore', 'v.', '/ɪkˈsplɔː/', '探索;勘探', 'People continue to explore space despite the great risks.', '尽管风险巨大,人们仍在继续探索太空。', 'The Call of the Challenger', 43, 0, 'senior', 'wordlist', 'elective4', 'U6', 'explore space', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'universe', 'n.', '/ˈjuːnɪvɜːs/', '宇宙;万物', 'The telescope showed us that the universe is far larger than we imagined.', '望远镜让我们看到,宇宙远比我们想象的要大。', 'The Call of the Challenger', 44, 0, 'senior', 'wordlist', 'elective4', 'U6', 'across the universe', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'atmosphere', 'n.', '/ˈætməsfɪə/', '大气层;气氛', 'The crew re-entered the atmosphere on their way back to Earth.', '机组人员在返回地球的途中重新进入大气层。', 'The Call of the Challenger', 45, 0, 'senior', 'wordlist', 'elective4', 'U6', 're-enter the atmosphere', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'investigate', 'v.', '/ɪnˈvestɪɡeɪt/', '调查;研究', 'Engineers worked hard to investigate the cause of the disaster.', '工程师们努力调查这场灾难的原因。', 'The Call of the Challenger', 46, 0, 'senior', 'wordlist', 'elective4', 'U6', 'investigate the cause', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'observatory', 'n.', '/əbˈzɒvətri/', '天文台;观测站', 'At the observatory you can learn about astronomy and watch the stars.', '在天文台你可以学习天文学并观察星星。', 'The Call of the Challenger', 47, 0, 'senior', 'wordlist', 'elective4', 'U6', 'at the observatory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lunar', 'adj.', '/ˈluːnə/', '月球的;月亮的', 'Millions watched the first lunar landing on television.', '数百万人在电视上观看了首次登月。', 'The Call of the Challenger', 48, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a lunar landing', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'distant', 'adj.', '/ˈdɪstənt/', '遥远的;远处的', 'We must keep reaching for the stars, no matter how distant they seem.', '无论星辰看上去多么遥远,我们都必须继续追寻。', 'The Call of the Challenger', 49, 0, 'senior', 'wordlist', 'elective4', 'U6', 'distant stars', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sacrifice', 'n.', '/ˈsækrɪfaɪs/', '牺牲;舍弃', 'The sacrifice of the Challenger crew still calls us to keep exploring.', '挑战者号机组的牺牲仍在召唤我们继续探索。', 'The Call of the Challenger', 50, 0, 'senior', 'wordlist', 'elective4', 'U6', 'a great sacrifice', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u6.01', '①义务 / 建议 / 许可 / 能力(must · have to · should · ought to · may · can · could)', 'A2', 12, '外研社版选择性必修第四册 U6 — 强制必要 → must / have to;建议劝告 → should / ought to;表示许可、被允许 → may / can;表示能力、能够 → can / could / be able to。靠语境(规定、劝告、获准、训练后会做)判断,只有一个情态自然成立。', 1, 'elective4', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u6.02', '②对现在情况的推测(must · may / might / could · can''t)', 'A2', 12, '外研社版选择性必修第四册 U6 — 有把握的肯定推断 → must be/do(看得见的证据);否定推断、绝无可能 → can''t be/do;没把握的可能 → may / might / could be。语境给出的证据强弱决定用哪一个,且四个选项中只有一个可能性词。', 2, 'elective4', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u6.03', '③对过去的推测与评论(must / can''t / should / needn''t / could / might + have done)', 'A2', 12, '外研社版选择性必修第四册 U6 — 对过去有把握的肯定 → must have done;绝无可能 → can''t have done;本该做却没做(批评/后悔)→ should have done;做了却没必要 → needn''t have done;过去本可能(未实现)→ could / might have done。干扰项常是意义相反的情态或漏掉 have 的现在式。', 3, 'elective4', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'All astronauts ____ pass a strict medical check before any space flight.', 'must', 'may', 'could', 'would', 'A', '出发前的硬性规定、必须做到 → 表强制必要的 must。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'You look exhausted; you ____ rest well before tomorrow''s launch.', 'may', 'should', 'can', 'might', 'B', '给对方提建议 → 表建议的 should。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Visitors ____ take photos in the space hall, but they must not touch the models.', 'must', 'should', 'may', 'would', 'C', '被允许做某事(获得许可)→ 表许可的 may。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Thanks to months of hard training, she ____ stay calm even in great danger.', 'should', 'may', 'must', 'could', 'D', '训练后具备了这种能力 → 表过去能力的 could。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'There is no air outside, so astronauts ____ wear a spacesuit when they leave the craft.', 'have to', 'may', 'might', 'could', 'A', '客观情况逼使、不得不 → 表客观必要的 have to。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'With this powerful telescope, we ____ see galaxies billions of light years away.', 'should', 'can', 'must', 'would', 'B', '借助望远镜而有此能力 → 表能力的 can。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'If you really want to join the programme, you ____ start exercising right now.', 'may', 'might', 'ought to', 'can', 'C', '提出忠告、理应去做 → 表建议的 ought to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), '"You ____ enter the control room now," the manager said. "Everything is ready."', 'must', 'should', 'would', 'may', 'D', '管理者给予许可 → 表许可的 may。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'The rule is strict: every crew member ____ obey the captain''s orders at once.', 'must', 'may', 'can', 'might', 'A', '严格规定、必须服从 → 表强制的 must。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Students ____ visit the space camp at weekends if they sign up in advance.', 'must', 'may', 'should', 'would', 'B', '事先报名便获准前往 → 表许可的 may。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Your hands are shaking; you ____ take a short break before the next test.', 'may', 'can', 'should', 'might', 'C', '关心地提建议 → 表建议的 should。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Safety comes first, so the engineers ____ check every part of the rocket twice.', 'may', 'could', 'would', 'must', 'D', '安全要求下必须做到 → 表强制必要的 must。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Even as a child, Yang Liwei ____ name many of the stars in the night sky.', 'could', 'must', 'should', 'may', 'A', '童年时便具备这种本领 → 表过去能力的 could。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Because water floats away, astronauts ____ add it to most of their food in space.', 'may', 'have to', 'might', 'could', 'B', '客观条件所迫、不得不 → 表客观必要的 have to。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'The application video is due tomorrow; you ____ submit it as soon as possible.', 'may', 'might', 'ought to', 'can', 'C', '理应尽快去做的忠告 → 表建议的 ought to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Reporters ____ watch the take-off from the special area near the launch site.', 'must', 'should', 'would', 'may', 'D', '记者获准在专区观看 → 表许可的 may。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Without enough oxygen, the crew ____ return to the station immediately.', 'must', 'may', 'can', 'might', 'A', '紧急情况下必须立刻返回 → 表强制必要的 must。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'After years of practice, these pilots ____ land the shuttle even in a storm.', 'should', 'can', 'must', 'would', 'B', '长期练习后具备这种能力 → 表能力的 can。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'If the weather looks bad, you ____ delay the launch rather than take a risk.', 'may', 'can', 'should', 'might', 'C', '给出明智的建议 → 表建议的 should。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.01'), 'Trained for months, the young teacher ____ explain how gravity worked in space.', 'must', 'should', 'may', 'could', 'D', '经训练后能够做到 → 表过去能力的 could。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'The lights are on and I can hear voices, so the crew ____ be inside the module now.', 'must', 'can''t', 'needn''t', 'would', 'A', '有灯光、有人声为证据 → 有把握的肯定推断 must。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'That bright dot ____ be a star; it is moving far too fast across the sky.', 'must', 'can''t', 'may', 'should', 'B', '移动太快、绝不可能是星 → 否定推断 can''t。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'Scientists are still not sure, but there ____ be simple life on some distant planets.', 'must', 'can''t', 'might', 'should', 'C', '尚不确定的可能性 → 没把握的 might。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'She knows every part of the rocket, so she ____ be a real expert.', 'can''t', 'needn''t', 'would', 'must', 'D', '了如指掌为证据 → 有把握的肯定推断 must。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'He ____ be in the spacecraft now; I have just seen him in the control room.', 'can''t', 'must', 'may', 'should', 'A', '刚见到他在别处 → 绝无可能的否定推断 can''t。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'We don''t know yet, but a planet like ours ____ have water on its surface.', 'must', 'could', 'can''t', 'should', 'B', '未知的一种可能 → 没把握的 could。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'The screen shows the engine is running, so everything ____ be working well.', 'can''t', 'needn''t', 'must', 'would', 'C', '仪表为证 → 有把握的肯定推断 must。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'Eric isn''t certain, but life out there ____ look quite different from us.', 'must', 'can''t', 'should', 'may', 'D', '不确定的可能 → 没把握的 may。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'This ____ be the right answer; the numbers simply do not add up.', 'can''t', 'must', 'may', 'should', 'A', '数字对不上、不可能正确 → 否定推断 can''t。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'Look at all that smoke and fire — something ____ be seriously wrong.', 'can''t', 'must', 'needn''t', 'would', 'B', '浓烟烈火为证据 → 有把握的肯定推断 must。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'Take a coat; the evening at the observatory ____ get rather cold.', 'must', 'can''t', 'might', 'should', 'C', '对入夜可能变冷的推测 → 没把握的 might。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'The signal is far too weak; it ____ be coming from a nearby planet.', 'must', 'may', 'should', 'can''t', 'D', '信号太弱、不可能来自近处 → 否定推断 can''t。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'Her eyes are red and she keeps crying, so she ____ feel terribly sad.', 'must', 'can''t', 'needn''t', 'would', 'A', '红眼、哭泣为证 → 有把握的肯定推断 must。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'No one is certain, but dark matter ____ be made of tiny unknown particles.', 'must', 'could', 'can''t', 'should', 'B', '未确定的科学可能 → 没把握的 could。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'The telescope cost millions of pounds, so its images ____ be extremely clear.', 'can''t', 'needn''t', 'must', 'would', 'C', '造价昂贵为依据 → 有把握的肯定推断 must。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'The launch is not confirmed, but it ____ take place early tomorrow morning.', 'must', 'can''t', 'should', 'may', 'D', '尚未确定的可能 → 没把握的 may。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'You ____ be serious; no one could survive in space without a spacesuit.', 'can''t', 'must', 'may', 'should', 'A', '对荒谬说法的否定 → 绝无可能的 can''t。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'Keep watching the sky tonight; you ____ even catch sight of a shooting star.', 'must', 'might', 'can''t', 'should', 'B', '也许会看到的可能 → 没把握的 might。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'All the warning lights are flashing, so the test ____ be about to begin.', 'can''t', 'needn''t', 'must', 'would', 'C', '信号灯闪烁为证据 → 有把握的肯定推断 must。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.02'), 'We aren''t sure of the cause, but a small crack ____ be the reason for the leak.', 'must', 'can''t', 'should', 'could', 'D', '未确定的一种可能原因 → 没把握的 could。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'The ground is scorched and smoking; the rocket ____ a huge trail of fire.', 'must have left', 'can''t have left', 'needn''t have left', 'must leave', 'A', '现场痕迹为证 → 对过去有把握的 must have left;must leave 漏掉 have 是现在式,错。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'You ____ the oxygen tank earlier; now it is far too late to fix it.', 'must have checked', 'should have checked', 'can''t have checked', 'should check', 'B', '本该检查却没检查 → 含批评的 should have checked;should check 是现在式,错。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'You ____ so much; the landing went perfectly in the end.', 'must have worried', 'can''t have worried', 'needn''t have worried', 'needn''t worry', 'C', '担心了却没必要 → needn''t have worried;needn''t worry 现在式,错。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'If she had lived, she ____ a whole new generation of scientists.', 'must have inspired', 'can''t have inspired', 'needn''t have inspired', 'might have inspired', 'D', '与过去事实相反、本可能实现却未实现 → might have inspired。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'He ____ the comet last night; the sky was completely covered with cloud.', 'can''t have seen', 'must have seen', 'should have seen', 'can''t see', 'A', '满天乌云、不可能看见 → 对过去的否定推断 can''t have seen;can''t see 现在式,错。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'All seven seats are empty, so the crew ____ the shuttle already.', 'can''t have boarded', 'must have boarded', 'needn''t have boarded', 'must board', 'B', '座位皆空为证 → 有把握的 must have boarded;must board 现在式,错。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'The team ____ the parts more carefully before such a risky flight.', 'must have tested', 'can''t have tested', 'should have tested', 'should test', 'C', '本该更仔细检测却没做 → 含批评的 should have tested。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'With a little more fuel, the old rocket ____ a much higher orbit.', 'must have reached', 'can''t have reached', 'needn''t have reached', 'could have reached', 'D', '条件具备就本可能达到(未实现)→ could have reached。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'Her face is pale and her hands shake; the news ____ her deeply.', 'must have shocked', 'can''t have shocked', 'needn''t have shocked', 'must shock', 'A', '脸色、发抖为证 → 有把握的 must have shocked;must shock 现在式,错。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'You ____ your own water; they gave each of us a full bottle.', 'must have brought', 'needn''t have brought', 'can''t have brought', 'needn''t bring', 'B', '带了水却没必要 → needn''t have brought;needn''t bring 现在式,错。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'The signal died at noon, so the probe ____ working past midday.', 'must have kept', 'should have kept', 'can''t have kept', 'can''t keep', 'C', '信号正午即断、不可能继续工作 → 否定推断 can''t have kept。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'You ____ us about the storm; we walked straight into it.', 'must have told', 'can''t have told', 'should tell', 'should have told', 'D', '本该告诉却没告诉 → 含责备的 should have told;should tell 现在式,错。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'The lab door is open and the lights are on; someone ____ in early.', 'must have come', 'can''t have come', 'needn''t have come', 'must come', 'A', '门开灯亮为证 → 有把握的 must have come;must come 现在式,错。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'We were lucky; a small crack like that ____ a terrible accident.', 'must have caused', 'might have caused', 'can''t have caused', 'needn''t have caused', 'B', '本可能酿成大祸(幸而未发生)→ might have caused。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'You ____ so fast; the launch was put off by two whole hours.', 'must have hurried', 'can''t have hurried', 'needn''t have hurried', 'needn''t hurry', 'C', '赶得急却没必要 → needn''t have hurried;needn''t hurry 现在式,错。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'She ____ the whole report already; she only began writing an hour ago.', 'must have finished', 'should have finished', 'can''t finish', 'can''t have finished', 'D', '刚开始一小时、不可能写完 → 否定推断 can''t have finished。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'The data shows the engine overheated, so the fault ____ there.', 'must have started', 'can''t have started', 'needn''t have started', 'must start', 'A', '数据为证 → 有把握的 must have started;must start 现在式,错。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'They ____ to the engineers, who had warned them about the cold weather.', 'must have listened', 'should have listened', 'can''t have listened', 'should listen', 'B', '本该听劝却没听 → 含批评的 should have listened。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'If the rules had been obeyed, the disaster ____ avoided.', 'must have been', 'can''t have been', 'could have been', 'needn''t have been', 'C', '与过去事实相反、本可以避免 → could have been。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U6' AND code='fe4u6.03'), 'Look how exhausted the trainees are; the test ____ extremely hard.', 'can''t have been', 'needn''t have been', 'must be', 'must have been', 'D', '学员精疲力竭为证 → 有把握的 must have been;must be 现在式,错。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Teacher Among the Stars', 'When the Challenger space shuttle took off on 28 January 1986, the world had almost stopped wondering at what astronauts could do. Yet this flight was special. On board was Christa McAuliffe, an ordinary teacher and mother who was about to become the first civilian in space. She planned to give two short lessons from orbit, one to show the controls of the spacecraft and another to explain how gravity worked. Christa hoped her lessons would rekindle young people''s interest in space. With students across the nation watching, she might have inspired a whole new generation of scientists. Tragically, her dream ended just over a minute after take-off, when the shuttle exploded and all seven crew members were lost. Most people had assumed that such a flight would be no more dangerous than an ordinary plane journey. How wrong they had been. In an instant, excitement turned into shock, and the accident cast a long shadow on millions of hearts.', '记叙·挑战者号与平民教师', 160, '[{"q":"Why was the Challenger flight described as special?","answer":"A","options":["It carried an everyday schoolteacher who would be the first non-astronaut to fly into orbit.","It was the very first rocket ever launched.","It travelled all the way to another planet.","It had no crew on board at all."],"explanation":"原文 Christa 是首位进入太空的平民教师的转述。"},{"q":"What did Christa hope her lessons would achieve?","answer":"B","options":["Make space travel illegal.","Reawaken students'' enthusiasm for exploring space.","Replace all school teachers with robots.","Prove that space was completely safe."],"explanation":"原文 ''rekindle young people''s interest in space'' 的转述。"},{"q":"How did most people view the flight before the accident?","answer":"A","options":["As no more risky than a normal plane trip.","As certain to fail.","As a waste of money.","As the most dangerous mission ever planned."],"explanation":"原文 ''no more dangerous than an ordinary plane journey'' 的转述。"}]'::jsonb, '[{"word":"shuttle","cn":"航天飞机"},{"word":"civilian","cn":"平民"},{"word":"rekindle","cn":"重新唤起"},{"word":"crew","cn":"机组人员"}]'::jsonb, 2, 'elective4', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'One Small Step', 'Ever since Neil Armstrong first set foot on the Moon on 20 July 1969, people have grown used to the notion of space travel. But on that summer night, the world held its breath. Millions of families gathered around black and white television sets to watch the first lunar landing. They were well aware of how hazardous the journey was and of the many things that could go wrong. When Armstrong stepped down and spoke his famous words about a small step and a giant leap, something once thought impossible had finally been achieved. What few people realised was that the computer guiding the spacecraft was far weaker than the ones today''s students carry in their pockets. Even so, all three astronauts of the mission returned safely to Earth. After that night, space travel quickly came to seem unexceptional, as one new success followed another. Yet the courage shown by those early explorers still reminds us how much daring that first journey demanded.', '记叙·首次登月', 163, '[{"q":"How did families around the world follow the first Moon landing?","answer":"B","options":["They read about it weeks later in newspapers.","They watched it live on black and white televisions.","They heard nothing about it until 1980.","They saw it only in colour photographs."],"explanation":"原文 millions 围坐黑白电视机前观看的转述。"},{"q":"What surprising fact does the text give about the spacecraft''s computer?","answer":"C","options":["It was the most powerful machine on Earth.","It broke down during the landing.","It was much weaker than a modern student''s phone.","It was operated entirely by hand."],"explanation":"原文计算机比今天学生口袋里的还弱的转述。"},{"q":"What happened to people''s view of space travel after that night?","answer":"D","options":["They decided it should be stopped.","They thought it was impossible.","They lost all interest in science.","It soon came to feel quite ordinary."],"explanation":"原文 ''space travel quickly came to seem unexceptional'' 的转述。"}]'::jsonb, '[{"word":"notion","cn":"概念"},{"word":"lunar","cn":"月球的"},{"word":"hazardous","cn":"危险的"},{"word":"unexceptional","cn":"平常的"}]'::jsonb, 2, 'elective4', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Eyes Beyond the Earth', 'For thousands of years, people could see only a little of the night sky with the naked eye, and they understood even less of it. Everything changed when the first telescope was angled at the stars, for it increased the power of the human eye and showed that the universe was far larger than anyone had imagined. People learned that the Sun was only one star among billions in our galaxy, and that our galaxy was only one among billions more. Almost four hundred years later, the Hubble Space Telescope was launched into orbit. From beyond the Earth, it sent back the first truly clear pictures of distant clouds where stars are born, of huge black holes, and of new worlds where we might conceivably find life. Hubble also helped scientists work out the age of the universe and discover the astonishing fact that it is growing ever faster. Each new image reminds us how little of the cosmic ocean we have so far explored.', '说明·哈勃太空望远镜', 165, '[{"q":"What did the first telescope reveal about the universe?","answer":"A","options":["That it was far bigger than people had thought.","That it was much smaller than expected.","That it contained only one galaxy.","That nothing existed beyond the Sun."],"explanation":"原文望远镜显示宇宙远比想象大的转述。"},{"q":"What did the Hubble Space Telescope send back from orbit?","answer":"B","options":["Recordings of music from Earth.","Clear images of distant stars, black holes and possible new worlds.","Maps of the ocean floor.","Photos of ancient ruins on Earth."],"explanation":"原文哈勃传回遥远星云、黑洞、新世界图像的转述。"},{"q":"What surprising discovery did Hubble help scientists make?","answer":"C","options":["That the universe never changes.","That the Sun is the only star.","That the universe is expanding faster and faster.","That galaxies are shrinking."],"explanation":"原文宇宙以越来越快速度膨胀的转述。"}]'::jsonb, '[{"word":"telescope","cn":"望远镜"},{"word":"galaxy","cn":"星系"},{"word":"orbit","cn":"轨道"},{"word":"conceivably","cn":"有可能地"}]'::jsonb, 2, 'elective4', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Eye of Heaven', 'To see ever further into space, many countries are now building larger and more advanced telescopes. China operates the world''s largest and most powerful radio telescope, known as FAST and completed in 2016. People also call it the Eye of Heaven. Its great dish measures five hundred metres across, and it is being used in the search for dark matter. Dark matter is thought to be made of tiny subatomic particles that ordinary telescopes simply cannot see, because they are invisible to normal instruments. The huge dish can also study regions of space billions of light years away, right at the edge of the visible universe. A telescope like this gives astronomers a chance to answer questions that once seemed impossible. It shows, too, how a country can join humanity''s shared journey of exploration. As the engineers like to say, the more we learn about the universe, the more clearly we see how much still remains unknown.', '说明·中国天眼 FAST', 157, '[{"q":"What is FAST mainly being used to search for?","answer":"D","options":["New planets to live on.","Lost satellites.","Ancient bones.","Dark matter."],"explanation":"原文用于寻找暗物质的转述。"},{"q":"Why can ordinary telescopes not see dark matter?","answer":"A","options":["Its tiny particles cannot be seen by normal instruments.","It is too far underground.","It moves too slowly.","It only appears at night."],"explanation":"原文暗物质粒子对普通仪器不可见的转述。"},{"q":"What does the engineers'' saying suggest about exploration?","answer":"B","options":["Science has already answered every question.","The more we learn, the more we realise is still unknown.","Space is too dangerous to study.","Telescopes will soon be unnecessary."],"explanation":"原文学得越多越觉未知更多的转述。"}]'::jsonb, '[{"word":"subatomic","cn":"亚原子的"},{"word":"particle","cn":"粒子"},{"word":"invisible","cn":"看不见的"},{"word":"universe","cn":"宇宙"}]'::jsonb, 2, 'elective4', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Day in Zero Gravity', 'In space, even the most straightforward daily tasks can be difficult for astronauts who spend months on board a spacecraft. In a world without gravity, there is no up or down. Sleeping on the ceiling might sound like fun, but the crew must strap themselves into sleeping bags so they are not hurt while they float. Keeping clean is not simple either. Astronauts use special soap and shampoo that need no water, and after brushing their teeth they spit into a towel. Because there is nothing to push against, their bones and muscles slowly grow weak, so they have to exercise every single day to stay fit. Even eating changes: water must be added to much of the food, and since salt and pepper would float away, these come in liquid form. A vacuum cleaner is handy too, used both to keep dust out of the filters and to fetch items that drift out of reach. Carrying out these tasks well helps the crew stay healthy and focused.', '说明·航天器上的日常生活', 168, '[{"q":"Why do astronauts strap themselves down to sleep?","answer":"C","options":["To stay warm at night.","To hear the alarm clock better.","To avoid floating and getting hurt.","To save space in the craft."],"explanation":"原文绑住自己以免漂浮受伤的转述。"},{"q":"Why must astronauts exercise every day?","answer":"D","options":["Because there is nothing else to do.","Because exercise replaces eating.","Because the rules forbid resting.","Because their bones and muscles weaken without gravity."],"explanation":"原文无重力使骨骼肌肉变弱的转述。"},{"q":"How is salt and pepper provided in space?","answer":"A","options":["In liquid form so they will not float away.","In large dry bags.","Not provided at all.","Mixed into the drinking water."],"explanation":"原文盐和胡椒以液体形式提供的转述。"}]'::jsonb, '[{"word":"straightforward","cn":"简单的"},{"word":"gravity","cn":"重力"},{"word":"muscle","cn":"肌肉"},{"word":"fetch","cn":"拿来"}]'::jsonb, 2, 'elective4', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Message to the Stars', 'Voyager 1 is the spacecraft that has travelled further from Earth than any other. On board it carries a special disc called the Sounds of Earth. The disc holds recordings of greetings in many languages, music, and natural sounds, together with photographs of our world. Scientists hope that one day a faraway civilisation might find it and learn a little about who we are. The idea behind the disc is simple but moving: even across the vast distance of space, human beings still wish to reach out and connect. It has now been more than thirty years since the loss of the Challenger crew, yet their courage takes its place beside that of other heroes of exploration. The memory of those who gave their lives reminds us that we must keep reaching for the stars, no matter how distant they seem. The sacrifice of the past calls quietly to the future, urging each new generation to continue humanity''s greatest journey of discovery.', '说明·旅行者一号与探索精神', 162, '[{"q":"What does the disc on board Voyager 1 contain?","answer":"B","options":["Maps of the Moon only.","Greetings, music, sounds and photographs of Earth.","A list of every astronaut''s name.","Plans for a new rocket."],"explanation":"原文光盘录有问候、音乐、声音和照片的转述。"},{"q":"Why did scientists send the disc into deep space?","answer":"C","options":["To test a new kind of music player.","To replace radio on Earth.","In the hope a distant civilisation might learn about us.","To measure the weight of the spacecraft."],"explanation":"原文希望遥远文明发现并了解我们的转述。"},{"q":"What does the memory of the Challenger crew remind us to do?","answer":"D","options":["To stop all space flights.","To forget the past quickly.","To explore only with robots.","To keep exploring however distant the stars are."],"explanation":"原文提醒我们继续追寻星辰的转述。"}]'::jsonb, '[{"word":"disc","cn":"光盘"},{"word":"distant","cn":"遥远的"},{"word":"sacrifice","cn":"牺牲"},{"word":"explore","cn":"探索"}]'::jsonb, 2, 'elective4', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U6', 'A Week at Space Camp', 'Last summer I spent a week at a space camp, and it was truly (1)____. On the first day we learned some basic (2)____ about astronomy in the observatory. Then we got the chance to design and (3)____ our own model rockets into the air. The most exciting part came when we tried the flight (4)____, a machine that makes you feel as if you are really flying. I put on a heavy (5)____ and went for a walk in ''zero gravity''. It felt so (6)____ that I almost forgot none of it was real. Floating around like that is strange, and a few campers even began to feel (7)____. Luckily, I was fine. Our trainers told us that real astronauts need great (8)____ to keep working in such conditions. By the end of the week, I (9)____ understood why people give years of their lives to space travel. I came home tired but proud, already (10)____ to go back next year.', 162, 2, '[{"q":"1","answer":"A","options":["awesome","empty","quiet","cheap"],"explanation":"truly awesome 真是太棒了。"},{"q":"2","answer":"B","options":["weather","theory","money","sport"],"explanation":"basic theory about astronomy 关于天文学的基础理论。"},{"q":"3","answer":"C","options":["eat","sell","launch","hide"],"explanation":"launch model rockets 发射模型火箭。"},{"q":"4","answer":"D","options":["garden","market","ticket","simulator"],"explanation":"flight simulator 飞行模拟器。"},{"q":"5","answer":"A","options":["spacesuit","umbrella","blanket","basket"],"explanation":"put on a spacesuit 穿上宇航服。"},{"q":"6","answer":"B","options":["boring","lifelike","cheap","silent"],"explanation":"so lifelike 如此逼真。"},{"q":"7","answer":"C","options":["proud","hungry","sick","calm"],"explanation":"feel sick(空间病)感到难受。"},{"q":"8","answer":"D","options":["money","luck","noise","self-discipline"],"explanation":"need great self-discipline 需要很强的自律。"},{"q":"9","answer":"A","options":["finally","hardly","never","rarely"],"explanation":"finally understood 终于明白。"},{"q":"10","answer":"B","options":["afraid","eager","sorry","unable"],"explanation":"eager to go back 渴望再去。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U6', 'A Boy Who Loved the Stars', 'Ever since he was little, Tom had loved looking up at the (1)____ sky. While other children played games, he would lie on the grass and (2)____ the stars for hours. His grandfather gave him a small (3)____ so that he could see the Moon more clearly. Through it, Tom studied the (4)____ surface of the Moon, with its mountains and shadows. He read every book he could find about space (5)____, from the first satellites to the latest missions. His dream was to become an (6)____ one day and travel beyond the Earth. People sometimes told him that the stars were too (7)____ to reach, but Tom never gave up hope. He knew the journey would be hard and even (8)____, yet that only made him want it more. ''One day,'' he said, ''I will (9)____ for the stars, no matter how far away they are.'' His teachers admired his (10)____ and were sure he would go far.', 159, 2, '[{"q":"1","answer":"C","options":["busy","narrow","night","empty"],"explanation":"night sky 夜空。"},{"q":"2","answer":"D","options":["sell","eat","buy","watch"],"explanation":"watch the stars 看星星。"},{"q":"3","answer":"A","options":["telescope","ticket","basket","mirror"],"explanation":"a small telescope 一架小望远镜。"},{"q":"4","answer":"B","options":["cheap","lunar","noisy","kind"],"explanation":"the lunar surface 月球表面。"},{"q":"5","answer":"C","options":["shopping","cooking","exploration","traffic"],"explanation":"space exploration 太空探索。"},{"q":"6","answer":"D","options":["actor","farmer","driver","astronaut"],"explanation":"become an astronaut 成为宇航员。"},{"q":"7","answer":"A","options":["distant","cheap","heavy","quiet"],"explanation":"too distant to reach 太遥远而够不到。"},{"q":"8","answer":"B","options":["funny","hazardous","easy","boring"],"explanation":"hard and even hazardous 艰难甚至危险。"},{"q":"9","answer":"C","options":["pay","wait","reach","hide"],"explanation":"reach for the stars 追寻星辰。"},{"q":"10","answer":"D","options":["money","noise","fear","courage"],"explanation":"admired his courage 钦佩他的勇气。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U6', 'The Night the First Satellite Flew', 'In 1957, the world''s first (1)____ was launched into space, and nothing was ever quite the same again. On that autumn night, families went outside and looked up, hoping to (2)____ a tiny moving light crossing the sky. Newspapers were full of the news, and many people could hardly (3)____ that such a thing was possible. The little machine could not do much by today''s (4)____, but at the time it felt like magic. It (5)____ around the Earth again and again, sending back simple signals. Scientists were (6)____ to learn how it behaved so far above the ground. The success encouraged other countries to begin their own space (7)____. Soon rockets were carrying animals, and then brave people, into (8)____. Looking back, that first small satellite (9)____ the start of a great adventure. It reminded everyone that humans had finally begun to (10)____ the door to outer space.', 149, 2, '[{"q":"1","answer":"A","options":["satellite","garden","market","lesson"],"explanation":"the first satellite 第一颗卫星。"},{"q":"2","answer":"B","options":["sell","spot","cook","paint"],"explanation":"spot a moving light 看到一束移动的光。"},{"q":"3","answer":"C","options":["sell","cook","believe","drive"],"explanation":"hardly believe 几乎不敢相信。"},{"q":"4","answer":"D","options":["gardens","markets","tickets","standards"],"explanation":"by today''s standards 以今天的标准看。"},{"q":"5","answer":"A","options":["circled","sold","painted","cooked"],"explanation":"circled around the Earth 绕地球运行。"},{"q":"6","answer":"B","options":["afraid","eager","angry","sorry"],"explanation":"eager to learn 急于了解。"},{"q":"7","answer":"C","options":["dinners","gardens","programmes","songs"],"explanation":"space programmes 太空计划。"},{"q":"8","answer":"D","options":["sleep","water","traffic","space"],"explanation":"into space 进入太空。"},{"q":"9","answer":"A","options":["marked","sold","ate","hid"],"explanation":"marked the start 标志着开始。"},{"q":"10","answer":"B","options":["lock","open","sell","paint"],"explanation":"open the door to space 打开通往太空的大门。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U6', 'Finding the Courage to Apply', 'When I first saw the advertisement for the space programme, I almost did not (1)____. I was excited, but a small voice inside told me I was not (2)____ enough. To take part, you had to (3)____ a three-minute video explaining why you would make a good candidate. The very idea made my heart (4)____ with fear. For days I could not decide. Then I remembered the (5)____ of the early astronauts, who had faced real danger and still climbed aboard their rockets. If they (6)____ such great danger and still went on, surely I could record a short video. So I sat down, took a deep breath, and (7)____ my fear aside. I spoke about my love of the stars and my (8)____ to explore the unknown. When I finally pressed ''send'', I felt (9)____ of myself for trying. Whatever the result, I had learned an important (10)____: courage is not having no fear, but acting in spite of it.', 161, 2, '[{"q":"1","answer":"C","options":["sleep","sell","apply","cook"],"explanation":"did not apply 没去申请。"},{"q":"2","answer":"D","options":["hungry","late","busy","brave"],"explanation":"not brave enough 不够勇敢。"},{"q":"3","answer":"A","options":["submit","eat","paint","hide"],"explanation":"submit a video 提交一段视频。"},{"q":"4","answer":"B","options":["sleep","race","sing","cook"],"explanation":"made my heart race 让我心跳加速。"},{"q":"5","answer":"C","options":["weather","price","courage","noise"],"explanation":"the courage of the astronauts 宇航员的勇气。"},{"q":"6","answer":"D","options":["sold","cooked","painted","faced"],"explanation":"faced such danger 面对这样的危险。"},{"q":"7","answer":"A","options":["pushed","sold","ate","painted"],"explanation":"pushed my fear aside 把恐惧推到一边。"},{"q":"8","answer":"B","options":["fear","wish","price","noise"],"explanation":"my wish to explore 想去探索的愿望。"},{"q":"9","answer":"C","options":["afraid","sorry","proud","bored"],"explanation":"felt proud of myself 为自己感到骄傲。"},{"q":"10","answer":"D","options":["price","ticket","garden","lesson"],"explanation":"learned an important lesson 学到重要一课。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U6', 'A Visit to the Observatory', 'Last weekend our class visited a large (1)____ on top of a quiet hill. We had come to learn about (2)____, the study of stars and planets. A friendly scientist showed us a huge (3)____ pointing up at the night sky. Through it, the Moon looked so close that we could see its (4)____ clearly, every hill and crater sharp and bright. The scientist explained that with the naked (5)____ we can see only a tiny part of the sky. He told us that our Sun is just one star among billions in our (6)____. Then he (7)____ the telescope towards a faint patch of light, which turned out to be a distant cloud where new stars are born. We were all (8)____ by what we saw. Before we left, he reminded us that the universe is still mostly (9)____, and that there is so much left to discover. I went home determined to keep (10)____ the night sky.', 159, 2, '[{"q":"1","answer":"A","options":["observatory","restaurant","factory","library"],"explanation":"an observatory 一座天文台。"},{"q":"2","answer":"B","options":["cooking","astronomy","farming","shopping"],"explanation":"learn about astronomy 学习天文学。"},{"q":"3","answer":"C","options":["basket","mirror","telescope","ladder"],"explanation":"a huge telescope 一架巨大的望远镜。"},{"q":"4","answer":"D","options":["price","noise","weather","surface"],"explanation":"see its surface 看见它的表面。"},{"q":"5","answer":"A","options":["eye","ear","hand","foot"],"explanation":"with the naked eye 用肉眼。"},{"q":"6","answer":"B","options":["garden","galaxy","market","village"],"explanation":"billions in our galaxy 银河系中数十亿颗。"},{"q":"7","answer":"C","options":["sold","ate","angled","painted"],"explanation":"angled the telescope 把望远镜斜对过去。"},{"q":"8","answer":"D","options":["bored","angry","sleepy","amazed"],"explanation":"all amazed 都惊叹不已。"},{"q":"9","answer":"A","options":["unknown","cheap","heavy","loud"],"explanation":"still mostly unknown 仍大多未知。"},{"q":"10","answer":"B","options":["selling","studying","cooking","hiding"],"explanation":"keep studying the night sky 继续研究夜空。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U6', 'My First Spacewalk', 'I will never forget my first (1)____ outside the spacecraft. Before I left the safety of the cabin, I had to put on my (2)____ very carefully and check it twice. My heart was beating fast, for I knew how (3)____ space could be. When the door opened, I floated out into the silent (4)____ and saw the blue Earth far below me. There was no up or down, and at first I felt a little (5)____. Slowly I learned to (6)____ my body with small, careful movements. Around me there was nothing but stars, shining like (7)____ in the dark. My job was to (8)____ a broken part back to the cabin, where my crewmates were waiting. It was harder than it sounds, because every tool kept trying to (9)____ away from my hands. When I finally finished and came back inside, the whole crew (10)____ with relief. I had done something I would remember for the rest of my life.', 162, 2, '[{"q":"1","answer":"C","options":["holiday","picnic","spacewalk","lesson"],"explanation":"my first spacewalk 我第一次太空行走。"},{"q":"2","answer":"D","options":["raincoat","blanket","hat","spacesuit"],"explanation":"put on my spacesuit 穿上宇航服。"},{"q":"3","answer":"A","options":["hazardous","cheap","funny","quiet"],"explanation":"how hazardous space could be 太空有多危险。"},{"q":"4","answer":"B","options":["market","darkness","garden","kitchen"],"explanation":"the silent darkness 寂静的黑暗。"},{"q":"5","answer":"C","options":["hungry","proud","afraid","sleepy"],"explanation":"felt a little afraid 有点害怕。"},{"q":"6","answer":"D","options":["sell","paint","cook","control"],"explanation":"control my body 控制身体。"},{"q":"7","answer":"A","options":["diamonds","stones","books","coins"],"explanation":"shining like diamonds 像钻石般闪耀。"},{"q":"8","answer":"B","options":["throw","fetch","sell","hide"],"explanation":"fetch a broken part 取回一个损坏的部件。"},{"q":"9","answer":"C","options":["sit","sleep","float","cook"],"explanation":"float away from my hands 从手中漂走。"},{"q":"10","answer":"D","options":["argued","slept","complained","cheered"],"explanation":"cheered with relief 如释重负地欢呼。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·对话 Joining the Space Camp', '外研社版选择性必修第四册 U6 · dialogue', 3, 'Mia: Leo, have you seen the advertisement for the summer space camp?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·短文 The First Person in Space', '外研社版选择性必修第四册 U6 · passage', 2, 'In 1961, Yuri Gagarin became the first person to travel into space.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·对话 Asking an Astronaut about Daily Life', '外研社版选择性必修第四册 U6 · dialogue', 3, 'Student: Excuse me, what is the hardest part of living in space?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·短文 How Astronauts Train', '外研社版选择性必修第四册 U6 · passage', 2, 'Becoming an astronaut takes years of hard training.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·对话 Is There Life Out There?', '外研社版选择性必修第四册 U6 · dialogue', 3, 'Sophie: Do you think there is life on other planets, Eric?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·短文 A Word about Courage', '外研社版选择性必修第四册 U6 · passage', 2, 'Here is something to remember about exploring the unknown.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Journal Entry about Living in Space(写一篇太空生活日记)', 'A Day on Board the Spacecraft', '假设你是一名航天员,在航天器上度过了第一天的24小时。请用英语写一篇约100词的日记,内容包括:① 你在航天器上做了哪些事(如失重中睡觉、锻炼、吃饭等);② 你的感受;③ 你最喜欢和最不喜欢的部分。注意:适当用上情态动词(如 have to / must / can / could),让推测与必要表达自然。', 'Suppose you are an astronaut who has spent the first 24 hours on board a spacecraft. Write a journal entry (about 100 words) including: 1) what you did on board (e.g. sleeping, exercising and eating in zero gravity); 2) how you felt; 3) the part you enjoyed most and the part you enjoyed least. Try to use modal verbs (have to, must, can, could) naturally.', '["做了什么(I had to strap myself in to sleep / I must exercise every day)","感受(At first everything felt strange, but it was awesome)","最喜欢 / 最不喜欢(What I enjoyed most was … The hardest part was …)","适当使用情态动词表必要与能力"]'::jsonb, 70, 100, 'Day 1 on board. What an awesome day it has been! In this world without gravity, there is no up or down, so I had to strap myself into a sleeping bag just to rest safely. In the morning I must have spent an hour cleaning the cabin, because dust floats everywhere. We have to exercise every day, or our muscles will grow weak, so I worked hard on the machine. Eating was the strangest part: I could not use ordinary salt, since it would simply float away. What I enjoyed most was looking down at the blue Earth through the window. The hardest part was getting used to floating, but I am sure I can do better tomorrow.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In this world without gravity, there is no up or down.","We have to exercise every day, or our muscles will grow weak.","I could not use ordinary salt, since it would simply float away.","The hardest part was getting used to floating, but I can do better tomorrow."]'::jsonb, '[{"wrong":"I must to exercise every day.","correct":"I must exercise every day.","note":"情态动词 must 后接动词原形,不加 to。"},{"wrong":"I had to strapped myself in.","correct":"I had to strap myself in.","note":"have to 后接动词原形 strap。"},{"wrong":"The dust floats everywhere, so I must cleaned the cabin.","correct":"The dust floats everywhere, so I had to clean the cabin.","note":"表过去的必要用 had to + 原形,不用 must + 过去式。"}]'::jsonb, '【太空生活日记结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U6', '{"title":"情态动词综合复习·义务/推测/modal + have done 速查","intro":"情态动词后接动词原形,表达说话人的态度:必要、建议、许可、能力,以及对现在或过去的推测。判断口诀:看语境给的『证据强弱』和『时间(现在 / 过去)』——现在推测用『情态 + do/be』,过去推测用『情态 + have done』。","table":{"headers":["用途","情态动词 / 例句"],"rows":[["强制必要","must / have to：Astronauts must wear a spacesuit outside."],["建议劝告","should / ought to：You should rest before the launch."],["许可","may / can：Visitors may take photos here."],["能力","can / could / be able to：She could stay calm in danger."],["现在·肯定推测","must be/do：The lights are on, so someone must be inside."],["现在·否定推测","can''t be/do：It moves too fast; it can''t be a star."],["现在·可能","may / might / could be：There might be life out there."],["过去推测/评论","must / can''t / should / needn''t / could + have done"]]},"specialRules":[{"rule":"must have done = 对过去有把握的肯定推断","mark":"The ground is wet; it must have rained."},{"rule":"can''t have done = 对过去绝无可能的否定推断","mark":"He can''t have seen it; it was too cloudy."},{"rule":"should have done = 本该做却没做(批评/后悔)","mark":"You should have checked the tank."},{"rule":"needn''t have done = 做了却没必要","mark":"You needn''t have worried; all went well."},{"rule":"could / might have done = 过去本可能(往往未实现)","mark":"She might have inspired a whole generation."}],"why":["现在推测看『现在的证据』→ 情态 + 动词原形;过去推测看『过去发生的事』→ 情态 + have done。把握程度从强到弱:must(几乎肯定)> may/might/could(也许)> can''t(几乎不可能)。"],"gaokaoPoints":["must / have to 在肯定句都表必要,但否定:mustn''t = 禁止,don''t have to / needn''t = 不必。","情态 + have done 是语法填空与单选高频:must have done(肯定) / can''t have done(否定) / should have done(本该)/ needn''t have done(白做了)的语义辨析。","情态动词后一律接动词原形,must to / can to 都是错的。"],"examVsReal":[{"exam":"You must finish it today.（考试:强制）","real":"You''ve got to finish it today.","note":"口语里常用 have got to / gotta 表必要,书面用 must / have to。"},{"exam":"It must have rained last night.（考试:对过去肯定推测）","real":"It must''ve rained last night.","note":"口语 must have 常缩成 must''ve,听力里要听出 /əv/ 这个弱读。"}]}'::jsonb, 'fltrp');
